INSERT INTO additive(id, code, slug, name_ru, name_en, group_code, status, origin, summary, eu_note, changed_2024, name_ru_norm, name_en_norm, summary_norm) VALUES (43, 'E960', 'steviolglikozidy', 'Стевиолгликозиды', 'Steviol glycosides', 'sweetener', 'allowed', 'гликозиды стевии', 'Подсластитель из гликозидов стевии. В перечне ЕАЭС разрешён. Порошок листьев, сироп и экстракты стевии — другая позиция, она из перечня исключена.', 'В ЕС разрешены стевиолгликозиды, а не лист стевии как таковой.', 0, 'ctebиoлглиkoзиды', 'steviol glycosides', 'пoдcлactиteль из глиkoзидob ctebии. b пepeчhe eaэc paзpeшeh. пopoшok лиctьeb, cиpoп и эkctpaktы ctebии — дpyгaя пoзиция, oha из пepeчhя иckлючeha.');
