INSERT INTO additive(id, code, slug, name_ru, name_en, group_code, status, origin, summary, eu_note, changed_2024, name_ru_norm, name_en_norm, summary_norm) VALUES (44, 'STEVIA-LEAF', 'steviya', 'Стевия: порошок листьев, сироп и экстракты', 'Stevia leaf powder, syrup and extracts', 'sweetener', 'excluded', 'растительное сырьё', 'Исключена из приложения 2 с 27.02.2024. Это не отменяет стевиолгликозиды E960: у них отдельная строка перечня и статус «разрешена».', 'Путаница листа и гликозидов — типичная ошибка справочников без различения объектов.', 1, 'ctebия: пopoшok лиctьeb, cиpoп и эkctpaktы', 'stevia leaf powder, syrup and extracts', 'иckлючeha из пpилoжehия 2 c 27.02.2024. эto he otmehяet ctebиoлглиkoзиды e960: y hиx otдeльhaя ctpoka пepeчhя и ctatyc «paзpeшeha».');
