INSERT INTO rule(id, title, scope, level, body, need_status, need_warning, need_code, need_changed, polyol_mode, polyol_value, need_category) VALUES ('R01', 'Добавка исключена из перечня', 'additive', 'forbid', 'Добавка исключена из приложения 2 ТР ТС 029/2012 с 27.02.2024. При производстве пищевой продукции в ЕАЭС её не применяют. Продукцию, выпущенную раньше, допускают только в пределах переходного периода и срока годности.', 'excluded', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO rule(id, title, scope, level, body, need_status, need_warning, need_code, need_changed, polyol_mode, polyol_value, need_category) VALUES ('R02', 'Надпись о внимании детей', 'additive', 'warn', 'Краситель разрешён, но на этикетке нужна надпись о влиянии на активность и внимание детей. Это касается E102, E104, E110, E122, E124 и E129.', NULL, 'children_activity', NULL, NULL, NULL, NULL, NULL);
INSERT INTO rule(id, title, scope, level, body, need_status, need_warning, need_code, need_changed, polyol_mode, polyol_value, need_category) VALUES ('R03', 'Источник фенилаланина', 'additive', 'warn', 'Для продукции с аспартамом на этикетке указывают: «Содержит источник фенилаланина». Без этой надписи маркировка неполна, хотя сама добавка в перечне есть.', NULL, 'phenylalanine', NULL, NULL, NULL, NULL, NULL);
INSERT INTO rule(id, title, scope, level, body, need_status, need_warning, need_code, need_changed, polyol_mode, polyol_value, need_category) VALUES ('R04', 'Доля сахароспиртов не задана', 'additive', 'check', 'Сахароспирт разрешён. Надпись о слабительном действии обязательна, если суммарная доля таких веществ в продукте больше 10 %. Введите долю, чтобы правило могло выбрать вывод.', NULL, 'laxative', NULL, NULL, 'unset', NULL, NULL);
INSERT INTO rule(id, title, scope, level, body, need_status, need_warning, need_code, need_changed, polyol_mode, polyol_value, need_category) VALUES ('R05', 'Надпись о слабительном действии', 'additive', 'warn', 'Доля сахароспиртов больше 10 %. На этикетке нужна надпись о слабительном действии при чрезмерном употреблении.', NULL, 'laxative', NULL, NULL, 'gt', 10, NULL);
INSERT INTO rule(id, title, scope, level, body, need_status, need_warning, need_code, need_changed, polyol_mode, polyol_value, need_category) VALUES ('R06', 'Доля сахароспиртов не выше 10 %', 'additive', 'info', 'Указанная доля сахароспиртов не выше 10 %. Предупреждающая надпись о слабительном действии по этому порогу не требуется. Норму подсластителя для вида продукции всё равно сверяют с приложением 13.', NULL, 'laxative', NULL, NULL, 'le', 10, NULL);
INSERT INTO rule(id, title, scope, level, body, need_status, need_warning, need_code, need_changed, polyol_mode, polyol_value, need_category) VALUES ('R07', 'Сульфиты в маркировке', 'additive', 'warn', 'Диоксид серы разрешён как добавка. Если суммарное содержание диоксида серы и сульфитов больше 10 мг/кг, их указывают среди компонентов, способных вызвать аллергическую реакцию (ТР ТС 022/2011).', NULL, 'allergen_sulfite', NULL, NULL, NULL, NULL, NULL);
INSERT INTO rule(id, title, scope, level, body, need_status, need_warning, need_code, need_changed, polyol_mode, polyol_value, need_category) VALUES ('R08', 'Нитрит вне мясной продукции', 'additive', 'check', 'Нитриты нормируются для отдельных видов продукции, в первую очередь мясной (приложения 8 и 17). Для выбранной категории прототип не подтверждает применение: нужен текст соответствующего приложения.', NULL, 'nitrite', NULL, NULL, NULL, NULL, NULL);
INSERT INTO rule_category_exclude(rule_id, category) VALUES ('R08', '');
INSERT INTO rule_category_exclude(rule_id, category) VALUES ('R08', 'мясная продукция');
INSERT INTO rule(id, title, scope, level, body, need_status, need_warning, need_code, need_changed, polyol_mode, polyol_value, need_category) VALUES ('R09', 'Нитрит для мясной продукции', 'additive', 'info', 'Для мясной продукции нитрит в принципе предусмотрен перечнем. Конкретный максимальный уровень и остаточное количество берут из приложений 8 и 17, прототип эти числа не подставляет.', NULL, 'nitrite', NULL, NULL, NULL, NULL, 'мясная продукция');
INSERT INTO rule(id, title, scope, level, body, need_status, need_warning, need_code, need_changed, polyol_mode, polyol_value, need_category) VALUES ('R10', 'Детское питание требует отдельной нормы', 'additive', 'check', 'Наличие добавки в приложении 2 не означает, что она допустима в детском питании. Для этой категории нормы заданы отдельными приложениями. Прототип оставляет проверку открытой и не ставит вывод «разрешено».', 'allowed', NULL, NULL, NULL, NULL, NULL, 'детское питание');
INSERT INTO rule(id, title, scope, level, body, need_status, need_warning, need_code, need_changed, polyol_mode, polyol_value, need_category) VALUES ('R11', 'Позиция изменена в 2024 году', 'additive', 'info', 'Строка перечня изменена редакцией, вступившей в силу 27.02.2024. Добавка не исключена, но норму нужно читать в действующем тексте, а не в редакции до 2024 года.', 'allowed', NULL, NULL, 1, NULL, NULL, NULL);
INSERT INTO rule(id, title, scope, level, body, need_status, need_warning, need_code, need_changed, polyol_mode, polyol_value, need_category) VALUES ('R12', 'Диоксид титана: ЕАЭС и ЕС расходятся', 'additive', 'info', 'В ЕАЭС E171 остаётся в приложении 2. В Европейском союзе с 7 августа 2022 г. диоксид титана не допущен как пищевая добавка. Один и тот же индекс нельзя переносить между рынками без проверки юрисдикции.', NULL, NULL, 'E171', NULL, NULL, NULL, NULL);
INSERT INTO rule(id, title, scope, level, body, need_status, need_warning, need_code, need_changed, polyol_mode, polyol_value, need_category) VALUES ('R13', 'Бензоат вместе с аскорбиновой кислотой в напитке', 'composition', 'warn', 'В напитках при совместном присутствии бензоата и аскорбиновой кислоты описано образование следовых количеств бензола. Это не запрет ТР ТС 029/2012, а технологический повод проверить рецептуру, pH и условия хранения.', NULL, NULL, NULL, NULL, NULL, NULL, 'напитки');
INSERT INTO rule_requires(rule_id, code) VALUES ('R13', 'E211');
INSERT INTO rule_requires(rule_id, code) VALUES ('R13', 'E300');
